/**
 * Type for icon names (keys of the icons object)
 */
export type IconName = keyof typeof icons;

/**
 * Get an icon path by name
 * @param name - The icon name in camelCase (e.g., 'QuestionCircleFilled')
 * @returns The icon path or undefined if not found
 */
export function getIcon(name: IconName): string {
  return icons[name];
}

/**
 * Get an icon path by name with fallback
 * @param name - The icon name
 * @param fallback - Fallback icon name if the requested icon doesn't exist
 * @returns The icon path
 */
export function getIconWithFallback(name: IconName, fallback: IconName): string {
  return icons[name] || icons[fallback];
}

/**
 * Check if an icon exists
 * @param name - The icon name to check
 * @returns True if the icon exists
 */
export function hasIcon(name: string): name is IconName {
  return name in icons;
}

/**
 * Get all available icon names
 * @returns Array of all icon names
 */
export function getAllIconNames(): IconName[] {
  return Object.keys(icons) as IconName[];
}

/**
 * Get icon by original name (with underscores)
 * @param originalName - The original icon name (e.g., 'Question_Circle_Filled')
 * @returns The icon path or undefined if not found
 */
export function getIconByOriginalName(originalName: string): string | undefined {
  const camelCaseName = originalName
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join('');
  return icons[camelCaseName as IconName];
}

// Re-export the icons map for direct access
export default icons;




